llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Oral lycopene, a highly lipophilic polyisoprenoid hydrocarbon structurally analogous to the query's long isoprenoid chain, had only 0.17% systemic availability in humans, directly supporting low oral bioavailability for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Curcumin, a poorly water-soluble lipophilic natural product, has around 1% oral bioavailability in humans due to poor solubility and extensive first-pass metabolism, supporting low F for the similarly lipophilic, poorly soluble query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Lacidipine, a highly lipophilic drug with extensive first-pass hepatic metabolism, has absolute oral bioavailability below 10% in volunteers, illustrating that high lipophilicity and first-pass liability lead to low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Finerenone, a small moderately lipophilic drug, had 43.5% absolute bioavailability in humans; however, its complete absorption and drug-like properties are not shared by the query, so this high-F evidence is outweighed by the low-F polyisoprenoid analogue data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an extremely lipophilic, high-molecular-weight polyisoprenoid quinone (CoQ9/10) with no ionizable groups and very poor predicted aqueous solubility. The most chemically analogous experimental evidence—lycopene, a polyisoprenoid hydrocarbon—shows very low oral systemic availability (0.2–2.6%) in humans. Curcumin and lacidipine also demonstrate low F for poorly soluble or highly lipophilic molecules. High-transfer small-molecule F values (e.g., finerenone, BI 425809) are not applicable because they lack the query's extreme physicochemical liabilities. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or CoQ9/10 in humans.",
    "Lycopene evidence comes from food-matrix or formulation contexts with variable absorption; transferability to the pure compound is uncertain.",
    "No direct data on the query's intestinal permeability, transporter involvement, or formulation-dependent absorption are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

